import math

def sigma(m):
    """Computes the sum of divisors function sigma(m)."""
    divisors = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)
    return sum(divisors)

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Find all m <= 100 such that sigma(m) is a perfect square
m_list = []
for m in range(2, 101):
    s = sigma(m)
    if is_square(s):
        m_list.append(m)

print(f"Integers m <= 100 such that sigma(m) is a perfect square: {m_list}")

