import math
from itertools import permutations

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_for_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # 1. Check total sum
    total_sum = sum(divisors)
    if not is_perfect_square(total_sum):
        return "No", None

    # 2. Search for a valid permutation using permutations (feasible for small n <= 6)
    # For m <= 20, the maximum number of divisors is d(12) = d(18) = 6.
    # 6! = 720, which is small enough for brute force checking permutations.

    for p in permutations(divisors):
        current_sum = 0
        is_valid_ordering = True

        for i in range(n):
            a_i = p[i]
            current_sum += a_i
            if not is_perfect_square(current_sum):
                is_valid_ordering = False
                break

        if is_valid_ordering:
            return "Yes", list(p)

    return "No", None

results = {}
for m in range(3, 21):
    result, ordering = solve_for_m(m)
    results[m] = {
        "divisors": get_divisors(m),
        "result": result,
        "ordering": ordering
    }

